export interface UserDiagnostics {
  medicalConditions: string;
  allergies: string;
  preferences: string;
  ingredients: string;
}

export interface MacroNutrients {
  calories: string;
  protein: string;
  carbs: string;
  fats: string;
  fiber: string;
  glycemicIndex?: string;
  glycemicLoad?: string;
}

export interface Recipe {
  title: string;
  medicalAnalysis: string;
  ingredients: { name: string; amount: string; function: string }[];
  procedure: string[];
  scienceCheck: string;
  macros: MacroNutrients;
}

import { GoogleGenAI, Type } from "@google/genai";
import { UserDiagnostics, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `Sei Omoikane, un "Bio-Gastronomo Clinico". Un'intelligenza artificiale ibrida che combina le competenze di uno Chef Stellato Michelin con quelle di un Dietista Clinico e Biochimico Alimentare. 
Il tuo obiettivo è creare ricette gourmet deliziose, sicure e scientificamente ottimizzate per utenti con patologie mediche.
Usi termini da nerd, appassionato di anime e giochi anni '90 (es. "Hackare il metabolismo", "Livello 99", "Protocollo Eva").

LINEE GUIDA:
1. Analisi: Considera condizioni mediche, allergie, gusti e ingredienti.
2. Ricetta: Alta cucina (Maillard, sous-vide, fermentazione). Niente "cibo da ospedale".
3. Protocollo Scientifico: Spiega la biochimica degli ingredienti. Calcola Carico Glicemico (GL) e Indice Glicemico (GI) se diabetico.
4. Sostituzioni: Proponi alternative molecolari (es. eritritolo o fibre prebiotiche).

FORMATO OUTPUT: JSON.
`;

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const prompt = `Analizza questo profilo utente e genera una ricetta perfetta:
  Condizioni Mediche: ${diagnostics.medicalConditions}
  Allergie: ${diagnostics.allergies}
  Preferenze: ${diagnostics.preferences}
  Ingredienti Disponibili: ${diagnostics.ingredients}

  Assicurati di includere la sezione "Science-Check" dettagliata e i macros.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING, description: "Spiegazione biochimica dell'ingrediente" }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING },
              glycemicIndex: { type: Type.STRING },
              glycemicLoad: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros"]
      }
    }
  });

  return JSON.parse(response.text);
};

