import React from 'react';
import { UserDiagnostics } from '../types';

interface Props {
  onSumbit: (data: UserDiagnostics) => void;
  isLoading: boolean;
}

const DiagnosticTerminal: React.FC<Props> = ({ onSumbit, isLoading }) => {
  const [formData, setFormData] = React.useState<UserDiagnostics>({
    medicalConditions: '',
    allergies: '',
    preferences: '',
    ingredients: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSumbit(formData);
  };

  return (
    <div className="glow-border bg-black/40 p-6 rounded-none relative overflow-hidden">
      <div className="absolute top-0 right-0 bg-green-900/30 px-2 py-1 text-[8px] border-l border-b border-green-500">INPUT_MODULE</div>

      <h2 className="header-font text-lg mb-4 text-green-300 flex items-center gap-2">
        <span className="w-2 h-2 bg-green-500 animate-pulse rounded-full"></span>
        DIAGNOSTICA_BIO_METABOLICA
      </h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-xs uppercase text-green-600 mb-1 font-bold">Condizioni Mediche / Patologie</label>
          <textarea 
            className="w-full bg-black border border-green-900 focus:border-green-400 p-2 text-sm text-green-100 outline-none h-20 placeholder:text-green-900"
            placeholder="Esempio: Diabete tipo 2, Ipertensione, Celiachia..."
            value={formData.medicalConditions}
            onChange={(e) => setFormData({...formData, medicalConditions: e.target.value})}
            required
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs uppercase text-green-600 mb-1 font-bold">Allergie / Intolleranze</label>
            <input 
              type="text"
              className="w-full bg-black border border-green-900 focus:border-green-400 p-2 text-sm text-green-100 outline-none placeholder:text-green-900"
              placeholder="Noci, Glutine, Lattosio..."
              value={formData.allergies}
              onChange={(e) => setFormData({...formData, allergies: e.target.value})}
            />
          </div>
          <div>
            <label className="block text-xs uppercase text-green-600 mb-1 font-bold">Preferenze di Gusto</label>
            <input 
              type="text"
              className="w-full bg-black border border-green-900 focus:border-green-400 p-2 text-sm text-green-100 outline-none placeholder:text-green-900"
              placeholder="Piccante, Giapponese, Mediterraneo..."
              value={formData.preferences}
              onChange={(e) => setFormData({...formData, preferences: e.target.value})}
            />
          </div>
        </div>

        <div>
          <label className="block text-xs uppercase text-green-600 mb-1 font-bold">Hardware Disponibile (Ingredienti)</label>
          <input 
            type="text"
            className="w-full bg-black border border-green-900 focus:border-green-400 p-2 text-sm text-green-100 outline-none placeholder:text-green-900"
            placeholder="Pollo, Tofu, Spinaci, Farina di ceci..."
            value={formData.ingredients}
            onChange={(e) => setFormData({...formData, ingredients: e.target.value})}
          />
        </div>

        <button 
          disabled={isLoading}
          className={`w-full py-3 header-font font-bold text-sm uppercase tracking-widest transition-all duration-300 ${
            isLoading 
              ? 'bg-green-900 text-green-800 cursor-not-allowed' 
              : 'bg-green-600/20 text-green-400 hover:bg-green-500 hover:text-black border border-green-500'
          }`}
        >
          {isLoading ? 'HACKING METABOLISM IN PROGRESS...' : 'ESEGUI PROTOCOLLO RICETTA'}
        </button>
      </form>
    </div>
  );
};

