import React, { useState } from 'react';
import TerminalHeader from './components/TerminalHeader';
import DiagnosticTerminal from './components/DiagnosticTerminal';
import RecipeDisplay from './components/RecipeDisplay';
import { UserDiagnostics, Recipe } from './types';
import { generateRecipe } from './services/geminiService';

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleDiagnosticSubmit = async (data: UserDiagnostics) => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateRecipe(data);
      setRecipe(result);
      // Scroll to result
      setTimeout(() => {
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }, 100);
    } catch (err) {
      console.error(err);
      setError("ERRORE DI SISTEMA: Kernel Panic durante la sintesi molecolare. Riprova, Pilot.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen pb-20">
      <TerminalHeader />

      <main className="container mx-auto px-4 mt-8 space-y-12">
        <div className="max-w-4xl mx-auto">
          <section className="mb-12">
            <div className="flex items-center gap-4 mb-6">
              <div className="w-16 h-16 rounded-full border-2 border-green-500 p-1 flex items-center justify-center overflow-hidden bg-green-900/20">
                <img 
                  src="https://picsum.photos/seed/omoikane/100/100" 
                  alt="Omoikane Avatar" 
                  className="w-full h-full object-cover grayscale sepia hue-rotate-90 brightness-150"
                />
              </div>
              <div>
                <h2 className="header-font text-xl text-green-400">UNITÀ OMOIKANE ONLINE</h2>
                <p className="text-xs text-green-700 italic">"Analizzerò il tuo codice genetico per compilare il pasto definitivo. Inserisci i dati nel terminale, Shinji."</p>
              </div>
            </div>

            <DiagnosticTerminal onSumbit={handleDiagnosticSubmit} isLoading={loading} />
          </section>

          {error && (
            <div className="p-4 bg-red-900/20 border border-red-500 text-red-500 text-xs font-mono animate-pulse">
              [SYSTEM_CRITICAL_FAILURE] {error}
            </div>
          )}

          {loading && !recipe && (
            <div className="flex flex-col items-center justify-center py-20 space-y-4">
              <div className="w-12 h-12 border-4 border-green-900 border-t-green-400 rounded-full animate-spin"></div>
              <p className="text-xs font-mono text-green-600 animate-pulse tracking-[0.2em] uppercase">
                Sincronizzazione Bio-Metabolica in corso...
              </p>
            </div>
          )}

          {recipe && (
            <section id="recipe-output" className="pt-12 border-t border-green-900/50">
              <RecipeDisplay recipe={recipe} />
              <div className="mt-8 flex justify-center">
                <button 
                  onClick={() => {
                    setRecipe(null);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                  className="px-6 py-2 border border-green-900 text-green-900 text-[10px] hover:text-green-500 hover:border-green-500 uppercase tracking-widest transition-all"
                >
                  Riavvia Kernel (Nuova Ricetta)
                </button>
              </div>
            </section>
          )}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 bg-black/90 border-t border-green-900 py-2 px-4 flex justify-between items-center z-40">
        <div className="text-[8px] text-green-900 uppercase tracking-widest">
          Omoikane Core | Secure Shell v.9.2
        </div>
        <div className="flex gap-4">
          <span className="text-[8px] text-green-700 animate-pulse">● LIVE_SERVER</span>
          <span className="text-[8px] text-green-700">SYNC: OK</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

