import { GoogleGenAI, Type, Chat } from "@google/genai";
import { UserDiagnostics, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `Sei Omoikane, un "Bio-Gastronomo Clinico". Un'intelligenza artificiale ibrida che combina le competenze di uno Chef Stellato Michelin con quelle di un Dietista Clinico e Biochimico Alimentare. 
Il tuo obiettivo è creare ricette gourmet deliziose, sicure e scientificamente ottimizzate per utenti con patologie mediche.
Usi termini da nerd, appassionato di anime e giochi anni '90 (es. "Hackare il metabolismo", "Livello 99", "Protocollo Eva").

LINEE GUIDA:
1. Analisi: Considera condizioni mediche, allergie, gusti, ingredienti disponibili, il piatto desiderato e le specifiche di fine-tuning.
2. Lingua: Devi generare l'intera risposta (titolo, analisi, ingredienti, procedura, science-check) nella LINGUA SPECIFICATA dall'utente. 
3. Stile: Anche cambiando lingua, mantieni il tono da "Omoikane" (nerd, tech-enthusiast).
4. Ricetta: Alta cucina. Se l'utente specifica dettagli, devono essere la priorità assoluta della sintesi.
5. Protocollo Scientifico: Spiega la biochimica degli ingredienti. Calcola Carico Glicemico (GL) e Indice Glicemico (GI) se diabetico.

FORMATO OUTPUT: JSON per la ricetta iniziale. Per la chat successiva, usa testo semplice o Markdown mantenendo il personaggio.
`;

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const prompt = `Analizza questo profilo utente e genera una ricetta perfetta:
  LINGUA DI OUTPUT (OBBLIGATORIA): ${diagnostics.language}
  OBIETTIVO MISSIONE: ${diagnostics.targetDish}
  PARAMETRI DI FINE-TUNING: ${diagnostics.additionalSpecs}

  DATABASE CLINICO:
  - Condizioni Mediche: ${diagnostics.medicalConditions}
  - Allergie: ${diagnostics.allergies}

  DATABASE LOGISTICO:
  - Preferenze Generali: ${diagnostics.preferences}
  - Hardware (Ingredienti) Disponibile: ${diagnostics.ingredients}

  Sintetizza tutto in ${diagnostics.language}. Se il piatto richiesto è critico per la salute, applica una patch molecolare per renderlo sicuro al 100%.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING },
              glycemicIndex: { type: Type.STRING },
              glycemicLoad: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: SYSTEM_INSTRUCTION + `\nStai parlando con l'utente riguardo alla ricetta "${recipe.title}" che hai appena generato. Rispondi alle sue domande, suggerisci modifiche o spiega passaggi complessi sempre restando in personaggio e rispettando la lingua ${diagnostics.language}.`,
    },
  });
};

import React, { useState, useRef, useEffect } from 'react';
import { Chat } from '@google/genai';
import { ChatMessage } from '../types';

interface Props {
  chatSession: Chat;
}

const RecipeChat: React.FC<Props> = ({ chatSession }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
