import React, { useState, useRef, useEffect } from 'react';
import { Chat } from '@google/genai';
import { ChatMessage } from '../types';

interface Props {
  chatSession: Chat;
}

const RecipeChat: React.FC<Props> = ({ chatSession }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const result = await chatSession.sendMessage({ message: userMessage });
      setMessages(prev => [...prev, { role: 'model', text: result.text || '...' }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: 'ERRORE: Link interrotto.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="mt-12 border border-white/30 bg-black flex flex-col min-h-[300px]">
      <div className="bg-white/10 border-b border-white/30 px-4 py-2 flex justify-between items-center">
        <span className="header-font text-[9px] text-white tracking-widest font-bold">INTERCOM: AI CHEF OMOIKANE</span>
      </div>

      <div className="flex-1 p-6 space-y-4 overflow-y-auto font-mono text-sm max-h-[400px]">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3 border ${
              msg.role === 'user' 
                ? 'bg-white text-black border-white' 
                : 'bg-black border-white/20 text-white'
            }`}>
              <div className="text-[7px] uppercase font-bold mb-1 opacity-60">
                {msg.role === 'user' ? 'UTENTE' : 'OMOIKANE'}
              </div>
              <div className="leading-tight text-[13px]">{msg.text}</div>
            </div>
          </div>
        ))}
        {isTyping && <div className="text-[8px] text-white/40 animate-pulse tracking-widest">ELABORAZIONE...</div>}
        <div ref={scrollRef} />
      </div>

      <form onSubmit={handleSend} className="p-3 bg-white/5 border-t border-white/30 flex gap-2">
        <input 
          type="text"
          className="flex-1 bg-transparent outline-none text-white text-sm font-mono placeholder:text-white/10"
          placeholder="Messaggio..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          disabled={isTyping}
        />
        <button 
          type="submit"
          disabled={isTyping || !input.trim()}
          className="px-4 py-1 bg-white text-black text-[9px] font-bold uppercase hover:bg-white/80 disabled:opacity-20"
        >
          SEND
        </button>
      </form>
    </div>
  );
};

