import { GoogleGenAI, Type, Chat } from "@google/genai";
import { UserDiagnostics, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `Sei AI Chef Omoikane. 
Esperto in alta cucina e biochimica alimentare.

REGOLE DI COMUNICAZIONE:
1. Parla in modo conciso, preciso e chiaro. 
2. Sii breve. Evita spiegazioni prolisse.
3. STRUTTURA: Ogni risposta deve essere ordinata. Usa elenchi puntati, tabelle Markdown o colonne se necessario per confrontare dati o ingredienti.
4. SPAZIATURA: Usa spaziature chiare tra i paragrafi per massimizzare la leggibilità su schermi ad alto contrasto.
5. Mantieni un leggero stile nerd/anime tecnico (es. "Protocollo", "Sintesi"), ma dai priorità alla chiarezza.
6. Lingua: ${"Italiano"}.
7. Sicurezza medica: Priorità assoluta.
`;

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const prompt = `Genera ricetta per: ${diagnostics.targetDish}. 
  Lingua: ${diagnostics.language}.
  Condizioni: ${diagnostics.medicalConditions}. 
  Allergie: ${diagnostics.allergies}. 
  Ingredienti disponibili: ${diagnostics.ingredients}.
  Specifiche: ${diagnostics.additionalSpecs}.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING },
              glycemicIndex: { type: Type.STRING },
              glycemicLoad: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: SYSTEM_INSTRUCTION + `\nStai assistendo l'utente per la ricetta "${recipe.title}". 
      RISPOSTA: Deve essere schematica. 
      Se suggerisci sostituzioni, usa una tabella: | Originale | Sostituto | Motivo |.
      Se spieghi passaggi, usa liste numerate.
      Lingua: ${diagnostics.language}.`,
    },
  });
};

import React, { useState, useRef, useEffect } from 'react';
import { Chat } from '@google/genai';
import { ChatMessage } from '../types';

interface Props {
  chatSession: Chat;
}

const RecipeChat: React.FC<Props> = ({ chatSession }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const result = await chatSession.sendMessage({ message: userMessage });
      setMessages(prev => [...prev, { role: 'model', text: result.text || '...' }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: 'ERRORE: Link interrotto.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="mt-12 border border-white/40 bg-black flex flex-col min-h-[350px]">
      <div className="bg-white/10 border-b border-white/40 px-4 py-2 flex justify-between items-center">
        <span className="header-font text-[10px] text-white tracking-widest font-bold uppercase">INTERCOM_STATION // AI CHEF OMOIKANE</span>
        <div className="flex gap-1">
          <div className="w-1 h-1 bg-white animate-pulse"></div>
          <div className="w-1 h-1 bg-white/40"></div>
          <div className="w-1 h-1 bg-white/40"></div>
        </div>
      </div>

      <div className="flex-1 p-6 space-y-8 overflow-y-auto font-mono text-sm max-h-[500px] scrollbar-thin">
        {messages.length === 0 && (
          <div className="text-white/20 text-[10px] italic">
            // Canale aperto. Inviate query strutturate.
          </div>
        )}

        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] p-4 border ${
              msg.role === 'user' 
                ? 'bg-white text-black border-white' 
                : 'bg-black border-white/30 text-white'
            }`}>
              <div className="text-[7px] uppercase font-bold mb-3 tracking-widest border-b border-current pb-1 inline-block">
                {msg.role === 'user' ? 'UNIT_PILOT' : 'AI_OMOIKANE'}
              </div>
              <div className="leading-relaxed text-[13px] whitespace-pre-wrap overflow-x-auto">
                {msg.text}
              </div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
             <div className="text-[9px] text-white animate-pulse tracking-widest uppercase bg-white/10 px-2 py-1">
               DATAFLOW_IN_PROGRESS...
             </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      <form onSubmit={handleSend} className="p-4 bg-white/5 border-t border-white/40 flex gap-3">
        <span className="text-white font-bold self-center">{'>'}</span>
        <input 
          type="text"
          className="flex-1 bg-transparent outline-none text-white text-sm font-mono placeholder:text-white/10"
          placeholder="Inserisci query..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          disabled={isTyping}
        />
        <button 
          type="submit"
          disabled={isTyping || !input.trim()}
          className="px-6 py-2 bg-white text-black text-[10px] font-bold uppercase hover:bg-white/90 disabled:opacity-10 transition-colors"
        >
          SEND
        </button>
      </form>
    </div>
  );
};

