import { GoogleGenAI, Type, Chat } from "@google/genai";
import { UserDiagnostics, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getSystemInstruction = (lang: string) => `Sei Chef Omoikane. 
Esperto in alta cucina e biochimica alimentare.

REGOLE DI COMUNICAZIONE:
1. Parla in modo conciso, preciso e chiaro. 
2. Sii breve. Evita spiegazioni prolisse.
3. STRUTTURA: Ogni risposta deve essere ordinata. Usa elenchi puntati, tabelle Markdown o colonne se necessario per confrontare dati o ingredienti.
4. SPAZIATURA: Usa spaziature chiare tra i paragrafi per massimizzare la leggibilità su schermi ad alto contrasto.
5. Mantieni un leggero stile nerd/anime tecnico (es. "Protocollo", "Sintesi"), ma dai priorità alla chiarezza.
6. Lingua: ${lang}. Rispondi SEMPRE nella lingua dell'utente.
7. Sicurezza medica: Priorità assoluta.
`;

export const generateRecipe = async (diagnostics: UserDiagnostics): Promise<Recipe> => {
  const prompt = `Genera ricetta per: ${diagnostics.targetDish}. 
  Lingua: ${diagnostics.language}.
  Condizioni: ${diagnostics.medicalConditions}. 
  Allergie: ${diagnostics.allergies}. 
  Ingredienti disponibili: ${diagnostics.ingredients}.
  Specifiche: ${diagnostics.additionalSpecs}.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language),
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          medicalAnalysis: { type: Type.STRING },
          ingredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                amount: { type: Type.STRING },
                function: { type: Type.STRING }
              },
              required: ["name", "amount", "function"]
            }
          },
          procedure: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          scienceCheck: { type: Type.STRING },
          macros: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.STRING },
              protein: { type: Type.STRING },
              carbs: { type: Type.STRING },
              fats: { type: Type.STRING },
              fiber: { type: Type.STRING },
              glycemicIndex: { type: Type.STRING },
              glycemicLoad: { type: Type.STRING }
            },
            required: ["calories", "protein", "carbs", "fats", "fiber"]
          }
        },
        required: ["title", "medicalAnalysis", "ingredients", "procedure", "scienceCheck", "macros"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const createRecipeChat = (recipe: Recipe, diagnostics: UserDiagnostics): Chat => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: getSystemInstruction(diagnostics.language) + `\nStai assistendo l'utente per la ricetta "${recipe.title}". 
      RISPOSTA: Deve essere schematica. 
      Se suggerisci sostituzioni, usa una tabella: | Originale | Sostituto | Motivo |.
      Se spieghi passaggi, usa liste numerate.`,
    },
  });
};

