import React, { useState, useMemo, useEffect } from 'react';
import TerminalHeader from './components/TerminalHeader';
import DiagnosticTerminal from './components/DiagnosticTerminal';
import RecipeDisplay from './components/RecipeDisplay';
import RecipeChat from './components/RecipeChat';
import { UserDiagnostics, Recipe, AppLanguage, AppTheme } from './types';
import { i18n } from './translations';
import { generateRecipe, createRecipeChat } from './services/geminiService';
import { Chat } from '@google/genai';

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [language, setLanguage] = useState<AppLanguage>('Italiano');
  const [theme, setTheme] = useState<AppTheme>('dark');

  const t = useMemo(() => i18n[language], [language]);

  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
  }, [theme]);

  const handleDiagnosticSubmit = async (data: UserDiagnostics) => {
    setLoading(true);
    setError(null);
    setRecipe(null);
    setChatSession(null);

    try {
      const result = await generateRecipe(data);
      setRecipe(result);
      const session = createRecipeChat(result, data);
      setChatSession(session);

      setTimeout(() => {
        const el = document.getElementById('recipe-output');
        el?.scrollIntoView({ behavior: 'smooth' });
      }, 300);
    } catch (err) {
      setError(t.error);
    } finally {
      setLoading(false);
    }
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <div className="min-h-screen pb-24 theme-transition font-mono selection:bg-white selection:text-black" style={{ color: 'var(--text-color)' }}>
      <TerminalHeader t={t} theme={theme} onThemeToggle={toggleTheme} />

      <main className="container mx-auto px-4 mt-12 space-y-16">
        <div className="max-w-5xl mx-auto">
          <section className="mb-16">
            <div className="flex items-center gap-6 mb-8 border-l border-white/40 pl-6" style={{ borderColor: 'var(--border-color)' }}>
              <div className="w-16 h-16 border p-1 grayscale" style={{ borderColor: 'var(--border-color)', backgroundColor: 'var(--sub-bg)' }}>
                <img 
                  src="https://picsum.photos/seed/chef/200/200" 
                  alt="Chef Omoikane" 
                  className="w-full h-full object-cover opacity-80"
                />
              </div>
              <div>
                <h2 className="header-font text-xl tracking-tighter uppercase italic" style={{ color: 'var(--text-color)' }}>CHEF OMOIKANE</h2>
                <p className="text-[10px] opacity-50 uppercase tracking-widest mt-1" style={{ color: 'var(--text-color)' }}>
                  {t.systemActive}
                </p>
              </div>
            </div>

            <DiagnosticTerminal 
              onSumbit={handleDiagnosticSubmit} 
              isLoading={loading} 
              language={language}
              setLanguage={setLanguage}
              t={t}
            />
          </section>

          {error && (
            <div className="p-4 border text-[10px] uppercase mb-12" style={{ borderColor: 'var(--text-color)', color: 'var(--text-color)' }}>
              [SYSTEM_ERROR] {error}
            </div>
          )}

          {loading && !recipe && (
            <div className="flex flex-col items-center justify-center py-24 space-y-4">
              <div className="w-12 h-0.5 opacity-20 overflow-hidden relative" style={{ backgroundColor: 'var(--text-color)' }}>
                <div className="absolute inset-0 w-1/3 animate-[loading-bar_1s_infinite_linear]" style={{ backgroundColor: 'var(--text-color)' }}></div>
              </div>
              <p className="text-[9px] opacity-60 tracking-[0.4em] uppercase" style={{ color: 'var(--text-color)' }}>{t.loading}</p>
            </div>
          )}

          {recipe && (
            <section id="recipe-output" className="pt-20 border-t" style={{ borderColor: 'var(--border-color)' }}>
              <RecipeDisplay recipe={recipe} t={t} />
              {chatSession && <RecipeChat chatSession={chatSession} t={t} />}
              <div className="mt-16 flex justify-center">
                <button 
                  onClick={() => {
                    setRecipe(null);
                    setChatSession(null);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                  className="px-8 py-2 border text-[9px] uppercase tracking-widest transition-all opacity-40 hover:opacity-100"
                  style={{ borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
                >
                  {t.newSynthesis}
                </button>
              </div>
            </section>
          )}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 border-t py-2 px-6 flex justify-between items-center z-40 backdrop-blur-md" style={{ backgroundColor: 'var(--header-bg)', borderColor: 'var(--border-color)' }}>
        <div className="text-[7px] opacity-30 uppercase tracking-widest font-bold" style={{ color: 'var(--text-color)' }}>
          CHEF OMOIKANE // V5.0
        </div>
        <div className="flex gap-4">
          <span className="text-[7px] opacity-60 tracking-widest uppercase" style={{ color: 'var(--text-color)' }}>STABLE</span>
        </div>
      </footer>

      <style>{`
        @keyframes loading-bar {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(300%); }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserDiagnostics, AppLanguage, Translations } from '../types';

interface Props {
  onSumbit: (data: UserDiagnostics) => void;
  isLoading: boolean;
  language: AppLanguage;
  setLanguage: (lang: AppLanguage) => void;
  t: Translations;
}

const LANGUAGES: { code: AppLanguage; label: string; flag: string }[] = [
  { code: 'Italiano', label: 'ITALIANO', flag: '🇮🇹' },
  { code: 'English', label: 'ENGLISH', flag: '🇬🇧' },
  { code: 'Japanese', label: '日本語', flag: '🇯🇵' },
  { code: 'Español', label: 'ESPAÑOL', flag: '🇪🇸' },
  { code: 'Chinese', label: '中文', flag: '🇨🇳' },
  { code: 'Français', label: 'FRANÇAIS', flag: '🇫🇷' },
];

const DiagnosticTerminal: React.FC<Props> = ({ onSumbit, isLoading, language, setLanguage, t }) => {
  const [isLangOpen, setIsLangOpen] = useState(false);
  const [formData, setFormData] = useState<UserDiagnostics>({
    medicalConditions: '',
    allergies: '',
    preferences: '',
    ingredients: '',
    targetDish: '',
    additionalSpecs: '',
    language: language
  });

  useEffect(() => {
    setFormData(prev => ({ ...prev, language }));
  }, [language]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSumbit(formData);
  };

  const selectedLang = LANGUAGES.find(l => l.code === language);

  return (
    <div className="glow-border p-6 rounded-none relative overflow-visible" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
      <div className="absolute top-0 right-0 flex flex-col items-end z-50">
        <div className="px-2 py-1 text-[8px] border-l border-b font-mono opacity-80" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}>
          SYS: OMOIKANE_V5
        </div>

        <div className="relative group">
          <button 
            type="button"
            onClick={() => setIsLangOpen(!isLangOpen)}
            className="border-l border-b px-3 py-2 flex items-center gap-2 hover:bg-white/10 transition-colors"
            style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
          >
            <span className="text-[14px]">{selectedLang?.flag}</span>
            <span className="text-[9px] font-bold tracking-widest">{selectedLang?.label}</span>
            <span className="text-[8px]">▼</span>
          </button>

          {isLangOpen && (
            <div className="absolute top-full right-0 w-40 border shadow-2xl overflow-hidden z-50" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)' }}>
              {LANGUAGES.map((lang) => (
                <button
                  key={lang.code}
                  type="button"
                  onClick={() => {
                    setLanguage(lang.code);
                    setIsLangOpen(false);
                  }}
                  className={`w-full text-left px-3 py-2 text-[9px] transition-colors flex items-center gap-2 ${
                    language === lang.code ? 'inverted-selection' : 'hover:bg-white/10'
                  }`}
                  style={language === lang.code ? { backgroundColor: 'var(--text-color)', color: 'var(--bg-color)' } : { color: 'var(--text-color)' }}
                >
                  <span>{lang.flag}</span>
                  {lang.label}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      <h2 className="header-font text-lg mb-6 flex items-center gap-2 tracking-tighter" style={{ color: 'var(--text-color)' }}>
        <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: 'var(--text-color)' }}></span>
        {t.synthesisParams}
      </h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="border-b pb-6" style={{ borderColor: 'var(--border-color)' }}>
          <label className="block text-[10px] uppercase mb-2 font-bold tracking-widest" style={{ color: 'var(--text-color)' }}>
            {t.targetDish}
          </label>
          <input 
            type="text"
            className="w-full border focus:border-opacity-100 p-4 text-sm outline-none font-mono"
            style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
            placeholder={t.targetDishPlace}
            value={formData.targetDish}
            onChange={(e) => setFormData({...formData, targetDish: e.target.value})}
            required
          />
        </div>

        <div className="p-4 border" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
          <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold tracking-widest" style={{ color: 'var(--text-color)' }}>
             {t.additionalSpecs}
          </label>
          <textarea 
            className="w-full border p-3 text-xs outline-none h-16 font-mono resize-none"
            style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
            placeholder={t.additionalSpecsPlace}
            value={formData.additionalSpecs}
            onChange={(e) => setFormData({...formData, additionalSpecs: e.target.value})}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.medicalConditions}</label>
            <textarea 
              className="w-full border p-3 text-xs outline-none h-24"
              style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
              placeholder={t.medicalConditionsPlace}
              value={formData.medicalConditions}
              onChange={(e) => setFormData({...formData, medicalConditions: e.target.value})}
              required
            />
          </div>
          <div>
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.ingredients}</label>
            <textarea 
              className="w-full border p-3 text-xs outline-none h-24"
              style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
              placeholder={t.ingredientsPlace}
              value={formData.ingredients}
              onChange={(e) => setFormData({...formData, ingredients: e.target.value})}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.allergies}</label>
            <input 
              type="text"
              className="w-full border p-3 text-xs outline-none"
              style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
              placeholder={t.allergiesPlace}
              value={formData.allergies}
              onChange={(e) => setFormData({...formData, allergies: e.target.value})}
            />
          </div>
          <div>
            <label className="block text-[9px] uppercase opacity-70 mb-2 font-bold" style={{ color: 'var(--text-color)' }}>{t.preferences}</label>
            <input 
              type="text"
              className="w-full border p-3 text-xs outline-none"
              style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}
              placeholder={t.preferencesPlace}
              value={formData.preferences}
              onChange={(e) => setFormData({...formData, preferences: e.target.value})}
            />
          </div>
        </div>

        <button 
          disabled={isLoading}
          className="w-full py-5 header-font font-bold text-xs uppercase tracking-[0.4em] transition-all duration-300 border disabled:opacity-30"
          style={{ backgroundColor: 'var(--text-color)', color: 'var(--bg-color)', borderColor: 'var(--text-color)' }}
        >
          {isLoading ? t.processing : t.submitBtn}
        </button>
      </form>
    </div>
  );
};

