import React, { useState, useEffect } from 'react';
import { Recipe, Translations } from '../types';
import { GoogleGenAI } from "@google/genai";

interface Props {
  recipe: Recipe;
  t: Translations;
}

const RecipeDisplay: React.FC<Props> = ({ recipe, t }) => {
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isVideoLoading, setIsVideoLoading] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const [videoError, setVideoError] = useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (isVideoLoading) {
      interval = setInterval(() => {
        setLoadingStep((prev) => (prev + 1) % t.videoLoading.length);
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [isVideoLoading, t.videoLoading.length]);

  const handleShare = async () => {
    const formattedRecipe = `
# ${recipe.title}
---
**${t.clinicalAnalysis}**
${recipe.medicalAnalysis}

**${t.hardware} (Ingredients)**
${recipe.ingredients.map(ing => `- ${ing.name}: ${ing.amount} (${ing.function})`).join('\n')}

**${t.protocol} (Procedure)**
${recipe.procedure.map((step, idx) => `${idx + 1}. ${step}`).join('\n')}

**${t.telemetry} (Macros)**
- Calories: ${recipe.macros.calories}
- Protein: ${recipe.macros.protein}
- Carbs: ${recipe.macros.carbs}
- Fats: ${recipe.macros.fats}
- Fiber: ${recipe.macros.fiber}

**${t.scienceLog}**
${recipe.scienceCheck}
    `.trim();

    if (navigator.share) {
      try {
        await navigator.share({
          title: recipe.title,
          text: formattedRecipe,
        });
      } catch (err) {
        copyToClipboard(formattedRecipe);
      }
    } else {
      copyToClipboard(formattedRecipe);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setShowCopyFeedback(true);
      setTimeout(() => setShowCopyFeedback(false), 2000);
    });
  };

  const generateVideoProtocol = async () => {
    setVideoError(null);
    const hasKey = await (window as any).aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await (window as any).aistudio.openSelectKey();
    }

    setIsVideoLoading(true);
    setLoadingStep(0);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `A professional cinematic cooking tutorial for ${recipe.title}. Close-up shots of high-quality ingredients being prepared. Steam rising from a pan. Elegant plating. 4k resolution, gourmet aesthetic. Procedure summary: ${recipe.procedure.slice(0, 3).join(". ")}`;

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 5000));
        operation = await ai.operations.getVideosOperation({operation: operation});
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      } else {
        throw new Error("Missing video URI");
      }
    } catch (err: any) {
      console.error(err);
      setVideoError(t.videoError);
      if (err.message?.includes("Requested entity was not found")) {
         await (window as any).aistudio.openSelectKey();
      }
    } finally {
      setIsVideoLoading(false);
    }
  };

  return (
    <div className="space-y-12 animate-in fade-in duration-700">
      <div className="glow-border p-10 rounded-none border-t-4 relative" style={{ backgroundColor: 'var(--bg-color)', borderColor: 'var(--border-color)', borderTopColor: 'var(--text-color)' }}>
        <div className="absolute top-4 right-10 flex flex-col items-end gap-2">
          <div className="flex gap-2">
            <button 
              onClick={handleShare}
              className="flex items-center gap-2 px-3 py-1.5 border border-white/20 text-[9px] uppercase font-bold tracking-widest hover:bg-white/10 transition-all"
              style={{ color: 'var(--text-color)', borderColor: 'var(--border-color)' }}
            >
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
              </svg>
              {t.shareBtn}
            </button>
            <button 
              onClick={generateVideoProtocol}
              disabled={isVideoLoading}
              className="flex items-center gap-2 px-3 py-1.5 border border-white/20 text-[9px] uppercase font-bold tracking-widest hover:bg-white/10 transition-all disabled:opacity-30"
              style={{ color: 'var(--text-color)', borderColor: 'var(--border-color)' }}
            >
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
              {t.generateVideo}
            </button>
          </div>
          {showCopyFeedback && (
            <span className="text-[7px] font-bold tracking-tighter opacity-80" style={{ color: 'var(--text-color)' }}>
              {t.copySuccess}
            </span>
          )}
        </div>

        <h2 className="header-font text-4xl font-black mb-6 tracking-tighter uppercase italic leading-tight pr-32" style={{ color: 'var(--text-color)' }}>
          {recipe.title}
        </h2>

        {isVideoLoading && (
          <div className="mb-10 p-12 border flex flex-col items-center justify-center space-y-6" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)' }}>
             <div className="flex gap-2">
                {[...Array(5)].map((_, i) => (
                  <div key={i} className={`w-2 h-2 ${i <= loadingStep ? 'bg-white' : 'bg-white/20'} animate-pulse`} style={i <= loadingStep ? { backgroundColor: 'var(--text-color)' } : { backgroundColor: 'var(--border-color)' }}></div>
                ))}
             </div>
             <p className="header-font text-[10px] tracking-[0.5em] uppercase text-center max-w-md" style={{ color: 'var(--text-color)' }}>
               {t.videoLoading[loadingStep]}
             </p>
          </div>
        )}

        {videoUrl && !isVideoLoading && (
          <div className="mb-10 border overflow-hidden shadow-2xl" style={{ borderColor: 'var(--border-color)' }}>
            <video 
              src={videoUrl} 
              controls 
              className="w-full aspect-video"
              poster="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 9'%3E%3Crect width='100%25' height='100%25' fill='%23000'/%3E%3C/svg%3E"
            />
          </div>
        )}

        {videoError && (
          <div className="mb-10 p-4 border border-red-500/50 text-[10px] uppercase font-bold" style={{ backgroundColor: 'rgba(255,0,0,0.05)', color: '#ff4444' }}>
            {videoError}
            <a 
              href="https://ai.google.dev/gemini-api/docs/billing" 
              target="_blank" 
              rel="noopener noreferrer"
              className="block mt-2 underline opacity-70 hover:opacity-100"
            >
              {t.billingLink}
            </a>
          </div>
        )}

        <div className="mb-10 p-6 border text-sm leading-relaxed font-mono" style={{ backgroundColor: 'var(--sub-bg)', borderColor: 'var(--border-color)', color: 'var(--text-color)' }}>
          <span className="font-bold block mb-2 uppercase text-[10px] tracking-[0.4em] opacity-80">{t.clinicalAnalysis}:</span>
          {recipe.medicalAnalysis}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
          <div className="lg:col-span-4 space-y-10">
            <div>
